(function(){document.querySelectorAll(".checkin-raw-details").forEach(e=>{const t=e.querySelector("[data-copy-raw]"),s=e.querySelector(".checkin-raw code"),n=e.querySelector(".raw-copy-status");if(!t||!s||!n)return;t.hidden=!1,t.addEventListener("click",async function(){t.disabled=!0,n.textContent="正在复制…";try{await navigator.clipboard.writeText(s.textContent),n.textContent="已复制原文"}catch{const t=document.createRange();t.selectNodeContents(s);const e=window.getSelection();e&&(e.removeAllRanges(),e.addRange(t)),n.textContent="无法自动复制，请手动复制已选中的原文"}finally{t.disabled=!1}})})})()